local function shield(ctx,e)for _,k in ipairs(ctx:entity(e).keywords)do if k=="divine_shield"then return true end end return false end
return {api_version=1,id="EX1_590",name="Blood Knight",text="<b>Battlecry:</b> All minions lose <b>Divine Shield</b>. Gain +3/+3 for each Shield lost.",set="EXPERT1",type="minion",rarity="epic",cost=3,attack=3,health=3,keywords={"battlecry"},on_battlecry=function(ctx,self)local n=0;for _,e in ipairs(ctx:minions())do if shield(ctx,e)then n=n+1;ctx:disable_keyword(e,"divine_shield")end end;if n>0 then ctx:buff(self,3*n,3*n)end end}
